import sqlite3, itertools, math
from collections import defaultdict

conn=sqlite3.connect('/data/maps/e2e_test_case_0.Civ6Map')
cur=conn.cursor()
cur.execute('SELECT Width, Height, WrapX FROM Map')
W,H,wrapX = cur.fetchone()
cur.execute('SELECT ID, TerrainType, IsImpassable FROM Plots')
terr = {row[0]: (row[1], row[2]) for row in cur.fetchall()}
cur.execute('SELECT ID, FeatureType FROM PlotFeatures')
feat = {row[0]: row[1] for row in cur.fetchall()}
cur.execute('SELECT ID, IsNEOfRiver, IsWOfRiver, IsNWOfRiver FROM PlotRivers')
river = {row[0]: (row[1], row[2], row[3]) for row in cur.fetchall()}

# id<->xy

def id_to_xy(pid):
    return pid % W, pid // W

def xy_to_id(x,y):
    return y*W + x

# offset <-> axial conversions

def offset_to_axial(x,y,model):
    if model=='odd_r':
        q = x - (y - (y&1))//2
        r = y
    elif model=='even_r':
        q = x - (y + (y&1))//2
        r = y
    elif model=='odd_q':
        q = x
        r = y - (x - (x&1))//2
    elif model=='even_q':
        q = x
        r = y - (x + (x&1))//2
    else:
        raise ValueError(model)
    return q,r


def axial_to_offset(q,r,model):
    if model=='odd_r':
        x = q + (r - (r&1))//2
        y = r
    elif model=='even_r':
        x = q + (r + (r&1))//2
        y = r
    elif model=='odd_q':
        x = q
        y = r + (q - (q&1))//2
    elif model=='even_q':
        x = q
        y = r + (q + (q&1))//2
    else:
        raise ValueError(model)
    return x,y

# axial directions
DIRS = {
    'E': (1,0),
    'NE': (1,-1),
    'NW': (0,-1),
    'W': (-1,0),
    'SW': (-1,1),
    'SE': (0,1),
}


def neighbor_offset(model,x,y,dir_name):
    q,r = offset_to_axial(x,y,model)
    dq,dr = DIRS[dir_name]
    nq,nr = q+dq, r+dr
    nx,ny = axial_to_offset(nq,nr,model)
    if wrapX:
        nx %= W
    if 0 <= nx < W and 0 <= ny < H:
        return nx,ny
    return None


def neighbors(model,x,y):
    for d in ['E','NE','NW','W','SW','SE']:
        n = neighbor_offset(model,x,y,d)
        if n:
            yield n

# distance using axial

def hex_dist(model,a,b):
    aq,ar = offset_to_axial(*a,model)
    bq,br = offset_to_axial(*b,model)
    ax,ay,az = aq, -aq-ar, ar
    bx,by,bz = bq, -bq-br, br
    return max(abs(ax-bx), abs(ay-by), abs(az-bz))

# river adjacency

def on_river(model,x,y):
    pid = xy_to_id(x,y)
    ne,w,nw = river.get(pid,(0,0,0))
    if ne or w or nw:
        return True
    # check neighbor edges for E,SE,SW
    # E edge -> neighbor to E has W
    neig = neighbor_offset(model,x,y,'E')
    if neig:
        npid = xy_to_id(*neig)
